/**
 * Service worker. Hand-written rather than generated by vite-plugin-pwa: the
 * app's whole offline story is already "fall back to the embedded snapshot",
 * so all this has to add is caching the shell that renders it.
 *
 * Two strategies, deliberately different:
 *
 *   Navigations   network-first, falling back to the cached shell. A stale
 *                 index.html would pin the app to an old JS bundle after a
 *                 deploy, so the network gets first refusal and the cache is
 *                 only reached when offline.
 *   Static assets cache-first. Vite fingerprints filenames, so a cached
 *                 `index-a1b2c3.js` is immutable by construction -- if the
 *                 content changes the name does too.
 *
 * The API is never cached. `/api/*` responses are a user's own portfolio and
 * a moving data snapshot; serving a stale one silently would be worse than
 * the app's existing, visible "Offline snapshot" badge.
 */

const VERSION = 'v1'
const SHELL_CACHE = `financert-shell-${VERSION}`
const ASSET_CACHE = `financert-assets-${VERSION}`

// Only paths that survive the build verbatim. Deliberately no CSS or JS:
// Vite fingerprints them (`styles.css` ships as `/assets/index-<hash>.css`),
// so naming them here would precache a 404 and would need regenerating on
// every build. The cache-first handler below picks them up on first load,
// which is what fingerprinted assets want anyway.
const SHELL = ['/', '/index.html', '/manifest.webmanifest', '/icons/icon-192.png']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // addAll is atomic: one 404 would reject the whole install and leave no
      // worker at all, so each entry is added independently.
      .then((cache) => Promise.allSettled(SHELL.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k !== SHELL_CACHE && k !== ASSET_CACHE).map((k) => caches.delete(k))),
      )
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  // Cross-origin includes the API on :8000 in dev and any CDN. Leave it alone.
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/api/')) return

  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone()
          caches.open(SHELL_CACHE).then((cache) => cache.put('/index.html', copy))
          return response
        })
        .catch(() => caches.match('/index.html').then((hit) => hit || caches.match('/'))),
    )
    return
  }

  event.respondWith(
    caches.match(request).then((hit) => {
      if (hit) return hit
      return fetch(request).then((response) => {
        // Only cache what actually succeeded; an opaque or errored response
        // stored here would be served back for the life of the cache.
        if (response.ok && response.type === 'basic') {
          const copy = response.clone()
          caches.open(ASSET_CACHE).then((cache) => cache.put(request, copy))
        }
        return response
      })
    }),
  )
})
